from pathlib import Path
import sys,json,copy,xml.etree.ElementTree as E,unittest
P=Path(__file__).resolve().parents[1];sys.path.insert(0,str(P/'source/tools'))
import test_danish_icelandic_norwegian_priority_wording as t
import nordic_priority_successors as n
import nordic_priority_binding as b
class PeerNegatives(unittest.TestCase):
 def test_all_763_coordinated_rows(self):
  data=t.fixture(b.NAME);count=0
  for tag,locale in data['locales'].items():
   for key,row in locale['values'].items():
    forged=copy.deepcopy(row);forged['target']+=' changed';forged['display']+=' changed'
    root=E.Element('resources');E.SubElement(root,'string',forged['attributes']).text=forged['target']
    with self.subTest(tag=tag,key=key),self.assertRaises(ValueError):t.require_complete(E.tostring(root,encoding='unicode'),key,forged)
    count+=1
  self.assertEqual(763,count)
 def test_xml_boundaries(self):
  for tag,locale in t.fixture(b.NAME)['locales'].items():
   key='colour_converter_unavailable';row=locale['values'][key]
   for variant in ('parent-text','tail','other-type','duplicate','child','attribute','wrong-root','root-attribute'):
    root=E.Element('resources');node=E.SubElement(root,'string',row['attributes']);node.text=row['target']
    if variant=='parent-text':root.text='forged'
    elif variant=='tail':node.tail='forged'
    elif variant=='other-type':E.SubElement(root,'plurals',{'name':key})
    elif variant=='duplicate':root.append(copy.deepcopy(node))
    elif variant=='child':E.SubElement(node,'b')
    elif variant=='attribute':node.set('translatable','false')
    elif variant=='wrong-root':root.tag='notresources'
    else:root.set('forged','yes')
    with self.subTest(tag=tag,variant=variant),self.assertRaises(ValueError):t.require_complete(E.tostring(root,encoding='unicode'),key,row)
 def test_cached_cohort_mutation(self):
  for tag in ('da','is','no','nn'):
   for section in ('values','context'):
    for field in ('target','display','attributes'):
     n.cohort.cache_clear();data=n.cohort();key=next(iter(data[tag][section]));row=data[tag][section][key]
     with self.subTest(tag=tag,section=section,field=field),self.assertRaises(TypeError):row[field]='forged'
     with self.subTest(tag=tag,section=section,nested=True),self.assertRaises(TypeError):row['attributes']['name']='forged'
     with self.assertRaises(TypeError):data[tag][section][key]={'target':'forged'}
  n.cohort.cache_clear()
if __name__=='__main__':unittest.main(verbosity=2)

